function renderChess(ctx,seconds,d){if(chessEngine){chessEngine.paint(ctx,seconds,d,fx);return}ctx.fillStyle=fx.endBlue;ctx.fillRect(0,0,960,540);ctx.fillStyle='#fff';ctx.font='16px Arial';ctx.textAlign='center';ctx.fillText(chessEngineError?'3D engine could not load. Reload to retry.':'Loading 3D scene…',480,270)}
