addFields('light',[['deskDelay','Desk reveal delay (s)',0,8,.1,'Immediate','Later']]);addFields('outdoor',[['teamReveal','Figure reveal duration (s)',.5,12,.1,'Fast','Slow'],['teamDelay','Figure reveal delay (s)',0,8,.1,'Immediate','Later']]);addFields('camera',[['cameraDelay','Wait before camera move (s)',0,8,.1,'Immediate','Later'],['dollyStart','Second parallax start (s)',0,18,.1,'Early','Late'],['dollyTime','Second parallax duration (s)',.5,10,.1,'Fast','Slow'],['dollyBack','Background pullback (%)',0,30,1,'Still','Back'],['dollyFront','Foreground push (%)',0,60,1,'Still','Forward'],['dollyDrop','Foreground drop (px)',0,150,1,'Still','Down'],['depth','House depth (%)',0,65,1,'Flat','Deep'],['portraitDepth','Portrait depth (%)',0,65,1,'Flat','Deep']]);addFields('finish',[['logoDelay','Logo start after camera (s)',0,20,.1,'Early','Late'],['redDelay','Red starts after camera (s)',0,20,.1,'Early','Late'],['blueHold','Hold blue before chess (s)',.1,4,.1,'Brief','Longer']]);
